1088	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1089	  result.compensationAttempts = outcome.attempts;
1090	  return result;
1091	}
1092	
1093	// The cancelled terminal shape: the run stops where it is, keeps the
1094	// context, trace and attempt records produced so far, and never carries a
1095	// success result. Compensation for already-succeeded actions is attached by
1096	// withCompensation under the usual rules.
1097	function cancelledResult(state) {
1098	  return {
1099	    status: 'cancelled',
1100	    context: state.context,
1101	    trace: state.trace,
1102	    actionAttempts: state.actionAttempts,
1103	  };
1104	}
1105	
1106	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1107	  const signal = resolveRunSignal(options);
1108	  const nodes = validateWorkflow(workflow);
1109	  verifyOperations(nodes, operations);
1110	
1111	  const state = createRunState(nodes, workflow, input);
1112	
1113	  // A signal that is already aborted stops the run before the first node —
1114	  // but only after the definition and the operation registrations above have
1115	  // been checked. Nothing executes and nothing is compensated.
1116	  if (signal && signal.aborted) {
1117	    return withCompensation(cancelledResult(state), state, operations);
1118	  }
1119	
1120	  for (;;) {
1121	    // Once the signal fires, no new regular node runs and no new business
1122	    // action attempt starts; the run ends cancelled with whatever state it
1123	    // reached, even if an end node was already visited on another branch.
1124	    if (signal && signal.aborted) {
1125	      return withCompensation(cancelledResult(state), state, operations);
1126	    }
1127	
1128	    const step = advanceSchedule(state);
1129	
1130	    if (step.kind === 'blocked') {
1131	      // Unmet dependencies end the run; successful compensable actions are
1132	      // rolled back even though an end node may already have been reached.
1133	      return withCompensation({
1134	        status: 'blocked', context: state.context, trace: state.trace,
1135	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1136	      }, state, operations);
1137	    }
1138	    if (step.kind === 'completed') {
1139	      // A completed run never invokes compensation.
1140	      return {
1141	        status: 'completed', result: state.endResult, context: state.context,
1142	        trace: state.trace, actionAttempts: state.actionAttempts,
1143	        compensationStatus: 'not_needed', compensationAttempts: [],
1144	      };
1145	    }
