1148	    const ready = step.node;
1149	    if (ready.type === 'action') {
1150	      const binding = actionBindings.get(ready);
1151	      if (binding.name !== null) {
1152	        // Nodes execute one at a time in declaration order; awaiting here
1153	        // never lets another node jump ahead.
1154	        const actionResult = await runBusinessAction(
1155	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1156	        if (!actionResult.ok) {
1157	          if (actionResult.cancelled) {
1158	            // Cancelled while the action was in flight or waiting to retry:
1159	            // the attempt records produced so far stay as they are.
